            weights[i] = sc.nextInt();
            heaviest = Math.max(heaviest, weights[i]);
            total += weights[i];
        }
        int q = sc.nextInt();
        for (int t = 0; t < q; t++) {
            int days = sc.nextInt();
            int lo = heaviest;
            int hi = total;
            while (lo < hi) {
                int mid = lo + (hi - lo) / 2;
                if (canShip(weights, mid, days)) {
                    hi = mid;
                } else {
                    lo = mid + 1;
                }
            }
            System.out.println("Days " + days + ": capacity " + lo);
        }
    }

